// === Tab: mySketch ===
var gridSize = 200;
let scale = 10;
var size;
var grid = [];
var pathers = [];
class Pather {
  constructor() {
    this.x = floor(random(0, gridSize));
    this.y = floor(random(0, gridSize));
    this.angle = grid[this.x][this.y]
    this.y *= size;
    this.x *= size;
  }
  update() {
    fill(255, 0, 0, 50);
    ellipse(this.x, this.y, 1, 1)
    let angle = p5.Vector.fromAngle((this.angle));
    this.x += angle.x;
    this.y += angle.y;
    this.x %= width;
    this.y %= height;
    if (this.x <= 0) this.x = width - 1
    let mx = floor(map(this.x, 0, width, 0, gridSize - 1));
    let my = floor(map(this.y, 0, height, 0, gridSize - 1));
    let newAngle = grid[mx][my];
    this.angle = lerp(this.angle, newAngle, .05);

  }

}

function setup() {
  createCanvas(windowWidth, windowHeight);
  //rectMode(CENTER)
  size = width / gridSize
  noStroke()
  for (let x = 0; x < gridSize; x++) {
    grid.push([]);
    for (let y = 0; y < gridSize; y++) {
      let x1 = x * width / gridSize
      let y1 = y * height / gridSize
      let curNoise = noise(x / scale, y / scale)
      fill(curNoise * 255)
      grid[x].push(map(curNoise, 0, 1, 0, TWO_PI))
      //rect(x1, y1, width / gridSize, height / gridSize)
      fill(255, 255, 0)

    }
  }
  for (let i = 0; i < 500; i++) {
    pathers.push(new Pather());
  }
  background(230)

}

function draw() {
  for (let pather of pathers) {
    pather.update();
  }

}
function mouseClicked() {
  grid = [];
  let z = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1);
  for (let x = 0; x < gridSize; x++) {
    grid.push([]);
    for (let y = 0; y < gridSize; y++) {
      var x1 = x * width / gridSize
      var y1 = y * height / gridSize
